const app = document.getElementById('productivity');
const S = { user:null, csrf:'', page:'inicio', q:'', taskQuery:'', taskStatus:'', taskPriority:'', taskSort:'prioridade', taskFrom:'', taskTo:'', taskView:'lista', tasks:[], events:[], docs:[], day:today(), calendarView:'mes', search:null, notifications:[], notificationPrefs:{}, plan:null, profile:null, dashboard:null, meetingQuery:'', meetingFrom:'', meetingTo:'', docQuery:'', docCategory:'', docFrom:'', docTo:'' };
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels = {aberta:'Aberta',em_andamento:'Em andamento',aguardando:'Aguardando',concluida:'Concluída',cancelada:'Cancelada'};
const priorityLabels = {baixa:'Baixa',normal:'Normal',alta:'Alta',urgente:'Urgente'};
const kindLabels = {reuniao:'Reunião',compromisso:'Compromisso',entrega:'Entrega de documento',prazo:'Prazo importante',atendimento:'Atendimento',lembrete:'Lembrete',evento_interno:'Evento interno'};
const categoryLabels = {administrativo:'Administrativo',oficio:'Ofícios',memorando:'Memorandos',relatorio:'Relatórios',ata:'Atas',formulario:'Formulários',portaria:'Portarias',referencia:'Referência',outros:'Outros'};
const pages = [['inicio','Visão geral'],['tarefas','Minhas tarefas'],['agenda','Minha agenda'],['reunioes','Reuniões e atas'],['documentos','Meus documentos'],['planejamento','Planejamento'],['perfil','Meu perfil']];
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function fmtDate(value,withTime=true){if(!value)return 'Sem prazo';const d=new Date(value.length===10?`${value}T12:00:00`:value);return Number.isNaN(d.getTime())?esc(value):new Intl.DateTimeFormat('pt-BR',withTime?{dateStyle:'short',timeStyle:'short'}:{dateStyle:'medium'}).format(d);}
function localStamp(value){return value?String(value).slice(0,16):'';}
function toDateKey(d){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function plusDays(d,n){const x=new Date(d);x.setDate(x.getDate()+n);return x;}
async function api(path, options={}){const headers={...(options.headers||{})};if(options.body&&typeof options.body!=='string'){headers['Content-Type']='application/json';options.body=JSON.stringify(options.body);}if(options.method&&options.method!=='GET')headers['X-CSRF-Token']=S.csrf;const response=await fetch(`/api${path}`,{credentials:'same-origin',...options,headers});const data=await response.json().catch(()=>({}));if(!response.ok)throw new Error(data.error||`Falha HTTP ${response.status}`);return data;}
function toast(message){const node=document.createElement('div');node.className='toast product-toast';node.setAttribute('role','status');node.textContent=message;document.body.append(node);setTimeout(()=>node.remove(),3500);}
function dueLate(task){return task.due_at&&task.due_at.slice(0,10)<today()&&!['concluida','cancelada'].includes(task.status);}
function nav(){return pages.map(([id,name])=>`<button type="button" class="${S.page===id?'active':''}" data-page="${id}">${name}</button>`).join('');}
function shell(content){app.innerHTML=`<header class="product-top"><div class="brand"><div class="brand-mark">S</div><div><h1>SIGAM · Minha rotina</h1><p>Organização pessoal e profissional</p></div></div><button class="button mobile-menu" data-action="menu">☰ Menu</button><nav class="product-nav" id="product-nav">${nav()}</nav><div class="product-tools"><form id="top-search-form"><input class="control product-search" id="global-search" name="q" type="search" placeholder="Pesquisar tudo…" value="${esc(S.q)}" aria-label="Pesquisa global"></form><button class="button" data-page="notificacoes" aria-label="Notificações">♢</button><span class="user-chip">${esc(S.user.name)}</span><button class="button" data-action="logout">Sair</button></div></header><main class="product-main">${content}</main>`;}
function heading(title,sub,actions=''){return `<div class="product-heading"><div><div class="eyebrow">SIGAM · Organização profissional</div><h2>${esc(title)}</h2><p>${esc(sub)}</p></div><div class="product-actions">${actions}</div></div>`;}
function panel(title,sub,body,classes=''){return `<section class="product-panel ${classes}"><div class="card"><div class="card-heading"><div><h3>${esc(title)}</h3>${sub?`<p>${esc(sub)}</p>`:''}</div></div>${body}</div></section>`;}
function stat(value,label,hint=''){return `<div class="stat"><strong>${value}</strong><span>${esc(label)}</span>${hint?`<em>${esc(hint)}</em>`:''}</div>`;}
function empty(message){return `<div class="empty-state">${esc(message)}</div>`;}
function itemActions(buttons){return `<div class="product-item-actions">${buttons}</div>`;}
async function loadPage(page=S.page){S.page=page;try{
 if(page==='inicio'){S.dashboard=await api(`/dashboard?date=${today()}`);}
 if(page==='tarefas')S.tasks=await api(`/tasks?q=${encodeURIComponent(S.taskQuery)}&status=${encodeURIComponent(S.taskStatus)}&priority=${encodeURIComponent(S.taskPriority)}&sort=${encodeURIComponent(S.taskSort)}&from=${encodeURIComponent(S.taskFrom)}&to=${encodeURIComponent(S.taskTo)}`);
 if(page==='agenda')await loadCalendarData();
 if(page==='reunioes')S.events=await api(`/events?kind=reuniao${S.meetingFrom?`&from=${S.meetingFrom}`:''}${S.meetingTo?`&to=${S.meetingTo}`:''}`);
 if(page==='documentos')S.docs=await api(`/documents?q=${encodeURIComponent(S.docQuery)}&category=${encodeURIComponent(S.docCategory)}&from=${encodeURIComponent(S.docFrom)}&to=${encodeURIComponent(S.docTo)}`);
 if(page==='planejamento'){[S.plan,S.tasks]=await Promise.all([api(`/plan?date=${today()}`),api(`/tasks?from=${today()}&to=${today()}`)]);}
 if(page==='perfil')S.profile=await api('/profile');
 if(page==='notificacoes')[S.notifications,S.notificationPrefs]=await Promise.all([api('/notifications'),api('/notifications/preferences')]);
 if(page==='pesquisa')S.search=await searchData(S.q);
 draw();
 }catch(error){if(error.message.includes('Autenticação'))renderSignedOut();else{shell(heading('Não foi possível carregar esta área',error.message,'<button class="button" data-action="reload">Tentar novamente</button>'));}}}
async function loadCalendarData(){let from,to;const base=new Date(`${S.day}T12:00:00`);if(S.calendarView==='dia'){from=S.day;to=S.day;}else if(S.calendarView==='semana'){const monday=plusDays(base,-((base.getDay()+6)%7));from=toDateKey(monday);to=toDateKey(plusDays(monday,6));}else{const first=new Date(base.getFullYear(),base.getMonth(),1,12);const start=plusDays(first,-((first.getDay()+6)%7));from=toDateKey(start);to=toDateKey(plusDays(start,41));}const [events,tasks]=await Promise.all([api(`/events?from=${from}&to=${to}`),api(`/tasks?from=${from}&to=${to}`)]);S.events=events;S.tasks=tasks;}
async function searchData(q){if(!q||q.trim().length<2)return {tasks:[],events:[],documents:[],notes:[]};return api(`/search?q=${encodeURIComponent(q.trim())}`);}
function draw(){switch(S.page){case'inicio':return drawDashboard();case'tarefas':return drawTasks();case'agenda':return drawCalendar();case'reunioes':return drawMeetings();case'documentos':return drawDocuments();case'planejamento':return drawPlanning();case'perfil':return drawProfile();case'notificacoes':return drawNotifications();case'pesquisa':return drawSearch();default:return drawDashboard();}}
function drawDashboard(){const d=S.dashboard||{counts:{},routine:[],upcomingEvents:[],recentDocuments:[],recentActivity:[]};const c=d.counts||{};const next=d.nextAction;
 const routine=d.routine.length?d.routine.map(x=>x.kind==='task'?`<article class="product-item"><div class="product-item-main"><span class="routine-kind">Tarefa · ${esc(priorityLabels[x.priority]||x.priority)}</span><h4>${esc(x.title)}</h4><p>${esc(labels[x.status]||x.status)} · ${fmtDate(x.due_at||x.start_at)}</p></div>${itemActions(`<button class="button" data-open-task="${x.id}">Abrir</button>`)}</article>`:`<article class="product-item"><div class="product-item-main"><span class="routine-kind">${esc(kindLabels[x.kind]||x.kind)}</span><h4>${esc(x.title)}</h4><p>${fmtDate(x.starts_at)}${x.location?` · ${esc(x.location)}`:''}</p></div>${itemActions(`<button class="button" data-open-event="${x.id}">Detalhes</button>`)}</article>`).join(''):empty('Sua rotina ainda está livre hoje.');
 const docs=d.recentDocuments.length?d.recentDocuments.map(x=>`<article class="product-item"><div class="product-item-main"><h4>${esc(x.title)}</h4><p>${esc(categoryLabels[x.category]||x.category)} · ${fmtDate(x.created_at)}</p></div>${itemActions(`<button class="button" data-page="documentos">Abrir documentos</button>`)}</article>`).join(''):empty('Seus documentos recentes aparecerão aqui.');
 const activity=d.recentActivity.length?d.recentActivity.map(x=>`<article class="product-item"><div class="product-item-main"><h4>${esc(x.summary)}</h4><small>${fmtDate(x.happened_at)}</small></div></article>`).join(''):empty('Suas atividades recentes aparecerão aqui.');
 shell(`${heading('Bom dia, '+(S.user.name||'servidor').split(' ')[0],`Seu resumo pessoal · ${fmtDate(today(),false)}`,`<button class="button button-primary quick-create" data-action="new-task">＋ Nova tarefa</button><button class="button" data-action="new-event">＋ Novo compromisso</button><button class="button" data-action="new-document">＋ Adicionar documento</button>`)}<section class="product-stats">${stat(c.abertas||0,'Tarefas abertas')}${stat(c.em_andamento||0,'Em andamento')}${stat(c.concluidas||0,'Concluídas')}${stat(c.atrasadas||0,'Atrasadas','Status preservado')}${stat(c.urgentes||0,'Urgentes')}</section><div class="product-grid">${panel('Minha rotina de hoje',`${d.routine.length} compromisso(s) ou tarefa(s)`,routine,'wide')}${panel('Próxima ação',next?`Prioridade ${priorityLabels[next.priority]} · ${next.due_at?fmtDate(next.due_at):'Sem prazo definido'}`:'Nenhuma tarefa pendente',next?`<div class="product-list"><article class="product-item"><div class="product-item-main"><h4>${esc(next.title)}</h4><p>${esc(next.description||'Sem descrição')}</p></div>${itemActions(`<button class="button button-primary" data-open-task="${next.id}">Ver tarefa</button>`)}</article></div>`:empty('Crie uma tarefa para planejar seu próximo passo.'),'third')}${panel('Próximos compromissos','Eventos agendados',d.upcomingEvents.length?`<div class="product-list">${d.upcomingEvents.map(e=>`<article class="product-item"><div class="product-item-main"><h4>${esc(e.title)}</h4><p>${esc(kindLabels[e.kind]||e.kind)} · ${fmtDate(e.starts_at)}</p></div>${itemActions(`<button class="button" data-open-event="${e.id}">Abrir</button>`)}</article>`).join('')}</div>`:empty('Nenhuma reunião futura cadastrada.'),'third')}${panel('Documentos recentes','Seus arquivos privados',docs,'third')}${panel('Atividade recente','Alterações feitas na sua conta',activity,'wide')}</div>`);}

function drawTasks(){const tasks=S.tasks;const filters=`<div class="filters-row"><input class="control" id="task-search" type="search" placeholder="Pesquisar tarefas…" value="${esc(S.taskQuery)}"><select class="control" id="task-status"><option value="">Todos os status</option>${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${S.taskStatus===k?'selected':''}>${v}</option>`).join('')}</select><select class="control" id="task-priority"><option value="">Todas as prioridades</option>${Object.entries(priorityLabels).map(([k,v])=>`<option value="${k}" ${S.taskPriority===k?'selected':''}>${v}</option>`).join('')}</select><select class="control" id="task-sort"><option value="prioridade" ${S.taskSort==='prioridade'?'selected':''}>Prioridade e prazo</option><option value="prazo" ${S.taskSort==='prazo'?'selected':''}>Prazo primeiro</option><option value="recentes" ${S.taskSort==='recentes'?'selected':''}>Mais recentes</option></select><input class="control" id="task-from" type="date" aria-label="Prazo a partir de" value="${esc(S.taskFrom)}"><input class="control" id="task-to" type="date" aria-label="Prazo até" value="${esc(S.taskTo)}"><div class="view-switch"><button class="button ${S.taskView==='lista'?'active':''}" data-action="task-view" data-view="lista">Lista</button><button class="button ${S.taskView==='kanban'?'active':''}" data-action="task-view" data-view="kanban">Quadro</button></div></div>`;
 let list;
 if(S.taskView==='kanban'){list=`<div class="kanban">${[['aberta','Aberta'],['em_andamento','Em andamento'],['aguardando','Aguardando'],['concluida','Concluída']].map(([status,label])=>`<section class="kanban-column"><h3>${label} · ${tasks.filter(t=>t.status===status).length}</h3>${tasks.filter(t=>t.status===status).map(t=>`<article class="kanban-card" data-open-task="${t.id}"><strong>${esc(t.title)}</strong><small><span class="badge priority-${t.priority}">${priorityLabels[t.priority]}</span> · ${t.due_at?fmtDate(t.due_at):'Sem prazo'}</small></article>`).join('')||'<small>Nenhuma tarefa</small>'}</section>`).join('')}</div>`;}
 else list=tasks.length?`<div class="product-list">${tasks.map(t=>`<article class="product-item"><div class="product-item-main"><span class="badge priority-${t.priority}">${esc(priorityLabels[t.priority])}</span> <span class="badge">${esc(labels[t.status])}</span><h4>${esc(t.title)}</h4><p>${esc(t.description||'Sem descrição')} · ${esc(t.category)}</p><small class="${dueLate(t)?'late':''}">${dueLate(t)?'Atrasada · ':''}${t.due_at?`Prazo ${fmtDate(t.due_at)}`:'Sem prazo'}${t.source_event_id?' · Criada em reunião':''}</small></div>${itemActions(`<select class="control compact-status" aria-label="Status de ${esc(t.title)}" data-task-status="${t.id}">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${t.status===k?'selected':''}>${v}</option>`).join('')}</select><button class="button" data-open-task="${t.id}">Detalhes</button>`)}</article>`).join('')}</div>`:empty('Nenhuma tarefa encontrada.');
 shell(`${heading('Minhas tarefas','Organize prazos e prioridades; tarefas atrasadas mantêm seu status.',`<button class="button button-primary" data-action="new-task">＋ Nova tarefa</button>`)}<section class="card">${filters}${list}</section>`);}

function eventEntries(){return [...S.events.map(e=>({type:'event',id:e.id,date:e.starts_at.slice(0,10),time:e.starts_at.slice(11,16),title:e.title,obj:e})),...S.tasks.filter(t=>t.due_at).map(t=>({type:'task',id:t.id,date:t.due_at.slice(0,10),time:t.due_at.slice(11,16),title:t.title,obj:t}))];}
function drawCalendar(){const entries=eventEntries();const focus=new Date(`${S.day}T12:00:00`);let cells=[];let title='';
 if(S.calendarView==='mes'){const first=new Date(focus.getFullYear(),focus.getMonth(),1,12);const start=plusDays(first,-((first.getDay()+6)%7));title=new Intl.DateTimeFormat('pt-BR',{month:'long',year:'numeric'}).format(focus);cells=Array.from({length:42},(_,i)=>plusDays(start,i));}
 else if(S.calendarView==='semana'){const monday=plusDays(focus,-((focus.getDay()+6)%7));title=`Semana de ${fmtDate(toDateKey(monday),false)}`;cells=Array.from({length:7},(_,i)=>plusDays(monday,i));}
 else{title=new Intl.DateTimeFormat('pt-BR',{dateStyle:'full'}).format(focus);cells=[focus];}
 const grid= S.calendarView==='lista'?`<div class="agenda-list">${entries.length?entries.sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(e=>`<article class="product-item"><div class="product-item-main"><div class="agenda-date">${fmtDate(e.date,false)}</div><h4>${esc(e.title)}</h4><p>${e.type==='task'?'Prazo de tarefa':esc(kindLabels[e.obj.kind]||e.obj.kind)} · ${e.time||'Horário não definido'}</p></div>${itemActions(`<button class="button" ${e.type==='task'?`data-open-task="${e.id}"`:`data-open-event="${e.id}"`}>Detalhes</button>`)}</article>`).join(''):empty('Nenhum compromisso ou prazo no período.')}</div>`:`<div class="calendar-grid" style="grid-template-columns:repeat(${S.calendarView==='dia'?1:7},minmax(0,1fr))">${S.calendarView==='mes'?['Seg','Ter','Qua','Qui','Sex','Sáb','Dom'].map(x=>`<div class="calendar-cell"><span class="calendar-day">${x}</span></div>`).join(''):''}${cells.map(day=>{const key=toDateKey(day);const items=entries.filter(e=>e.date===key);return `<div class="calendar-cell ${day.getMonth()!==focus.getMonth()&&S.calendarView==='mes'?'outside':''} ${key===today()?'today':''}"><span class="calendar-day">${S.calendarView==='mes'?day.getDate():fmtDate(key,false)}</span>${items.slice(0,S.calendarView==='mes'?3:20).map(e=>`<button class="calendar-entry ${e.type==='task'?'task':''}" ${e.type==='task'?`data-open-task="${e.id}"`:`data-open-event="${e.id}"`} title="${esc(e.title)}">${e.time?e.time+' · ':''}${esc(e.title)}</button>`).join('')}${items.length>(S.calendarView==='mes'?3:20)?`<small>+${items.length-(S.calendarView==='mes'?3:20)} mais</small>`:''}</div>`;}).join('')}</div>`;
 shell(`${heading('Minha agenda','Reuniões, compromissos e prazos de tarefas no horário local de Brasília.',`<button class="button button-primary" data-action="new-event">＋ Novo compromisso</button>`)}<section class="card"><div class="calendar-toolbar"><div class="toolbar"><button class="button" data-action="calendar-prev">‹</button><button class="button" data-action="calendar-today">Hoje</button><button class="button" data-action="calendar-next">›</button><strong>${esc(title)}</strong></div><div class="view-switch">${[['mes','Mês'],['semana','Semana'],['dia','Dia'],['lista','Lista']].map(([v,l])=>`<button class="button ${S.calendarView===v?'active':''}" data-action="calendar-view" data-view="${v}">${l}</button>`).join('')}</div></div>${grid}</section><div class="product-grid" style="margin-top:14px">${panel('Conflitos de horário','Eventos que se sobrepõem',findConflicts(entries),'wide')}</div>`);}
function findConflicts(entries){const events=S.events.filter(e=>e.status==='agendada'&&e.ends_at).sort((a,b)=>a.starts_at.localeCompare(b.starts_at));const found=[];for(let i=0;i<events.length;i++)for(let j=i+1;j<events.length;j++){if(events[j].starts_at<events[i].ends_at&&events[j].starts_at>=events[i].starts_at)found.push(`${events[i].title} × ${events[j].title} · ${fmtDate(events[i].starts_at)}`);}return found.length?`<div class="product-list">${found.map(x=>`<div class="conflict-notice">${esc(x)}</div>`).join('')}</div>`:empty('Nenhum conflito encontrado no período visível.');}

function drawMeetings(){const meetings=S.events.filter(e=>e.kind==='reuniao').sort((a,b)=>b.starts_at.localeCompare(a.starts_at));const q=S.meetingQuery||'';const shown=meetings.filter(e=>!q||`${e.title} ${e.agenda} ${e.minutes} ${e.participants}`.toLowerCase().includes(q.toLowerCase()));shell(`${heading('Reuniões e atas','Cadastre pautas, participantes, resultados e encaminhamentos.',`<button class="button button-primary" data-action="new-meeting">＋ Nova reunião</button>`)}<section class="card"><div class="filters-row"><input class="control" id="meeting-search" type="search" placeholder="Pesquisar reuniões e atas…" value="${esc(q)}"><label class="field">A partir de <input class="control" id="meeting-from" type="date" value="${esc(S.meetingFrom)}"></label><label class="field">Até <input class="control" id="meeting-to" type="date" value="${esc(S.meetingTo)}"></label></div>${shown.length?`<div class="product-list">${shown.map(e=>`<article class="product-item"><div class="product-item-main"><span class="badge">${e.status==='agendada'?'Agendada':e.status==='realizada'?'Realizada':'Cancelada'}</span><h4>${esc(e.title)}</h4><p>${fmtDate(e.starts_at)}${e.location?` · ${esc(e.location)}`:''}</p><small>${e.minutes?`Ata registrada · ${esc(e.minutes.slice(0,120))}`:'Ata ainda não registrada'}</small></div>${itemActions(`<button class="button" data-open-event="${e.id}">Ata e detalhes</button>`)}</article>`).join('')}</div>`:empty('Nenhuma reunião localizada.')}</section>`);}

function drawDocuments(){const docs=S.docs;const categoryOptions=Object.entries(categoryLabels).map(([k,v])=>`<option value="${k}" ${S.docCategory===k?'selected':''}>${v}</option>`).join('');shell(`${heading('Meus documentos','Arquivos privados desta conta. Somente você pode abrir e baixar estes documentos.',`<button class="button button-primary" data-action="new-document">＋ Adicionar documento</button>`)}<section class="card"><div class="filters-row"><input class="control" id="document-search" type="search" placeholder="Pesquisar por título ou arquivo…" value="${esc(S.docQuery)}"><select class="control" id="document-category"><option value="">Todas as categorias</option>${categoryOptions}</select><input class="control" id="document-from" type="date" aria-label="Adicionado a partir de" value="${esc(S.docFrom)}"><input class="control" id="document-to" type="date" aria-label="Adicionado até" value="${esc(S.docTo)}"></div>${docs.length?`<div class="product-list">${docs.map(d=>`<article class="product-item"><div class="product-item-main"><span class="badge">${esc(categoryLabels[d.category]||d.category)}</span>${d.attention?'<span class="badge priority-alta">Atenção</span>':''}<h4>${esc(d.title)}</h4><p>${esc(d.description||d.original_name)} · ${Math.max(1,Math.ceil(d.size_bytes/1024))} KB</p><small>${fmtDate(d.created_at,false)}${d.tag?` · ${esc(d.tag)}`:''}</small></div>${itemActions(`<a class="button" href="${esc(d.download_url)}">Baixar</a><button class="button" data-action="edit-document" data-id="${d.id}">Editar</button><button class="button button-danger" data-action="archive-document" data-id="${d.id}">Arquivar</button>`)}</article>`).join('')}</div>`:empty('Você ainda não adicionou documentos.')}</section><p class="muted-note">Arquivos até 8 MB. Tipos permitidos: PDF, Office, TXT, CSV, PNG e JPEG. Os arquivos ficam fora da pasta pública e o servidor valida sua sessão e propriedade em cada download.</p>`);}

function drawPlanning(){const p=S.plan||{priorities:'',dailyNotes:'',weeklyGoal:''};const taskList=S.tasks.length?`<div class="product-list">${S.tasks.map(t=>`<article class="product-item"><div class="product-item-main"><h4>${esc(t.title)}</h4><p><span class="badge priority-${t.priority}">${priorityLabels[t.priority]}</span> · ${esc(labels[t.status])} · ${t.due_at?fmtDate(t.due_at):'Sem prazo'}</p></div>${itemActions(`<button class="button" data-open-task="${t.id}">Abrir</button>`)}</article>`).join('')}</div>`:empty('Nenhuma tarefa com prazo para hoje.');shell(`${heading('Planejamento','Defina foco e anotações pessoais para hoje; tarefas mantêm seu próprio status.',`<button class="button" data-action="new-task">＋ Nova tarefa</button>`)}<div class="product-grid">${panel('Meu foco de hoje',`Plano pessoal · ${fmtDate(today(),false)}`,`<form class="detail" id="plan-form"><div class="field"><label for="plan-priorities">Prioridades do dia (uma por linha)</label><textarea class="control" id="plan-priorities" name="priorities" rows="4" maxlength="3000">${esc(p.priorities)}</textarea></div><div class="field"><label for="plan-notes">Notas rápidas</label><textarea class="control" id="plan-notes" name="dailyNotes" rows="5" maxlength="5000">${esc(p.dailyNotes)}</textarea></div><div class="field"><label for="plan-goal">Objetivo da semana</label><textarea class="control" id="plan-goal" name="weeklyGoal" rows="3" maxlength="3000">${esc(p.weeklyGoal)}</textarea></div><button class="button button-primary" type="submit">Salvar planejamento</button></form>`,'wide')}${panel('Tarefas de hoje','Ordenadas por prioridade e prazo',taskList,'wide')}</div>`);}

function drawProfile(){const p=S.profile||{};shell(`${heading('Meu perfil profissional','Atualize os dados profissionais autorizados. Cargo e setor não alteram suas permissões.',`<a class="button" href="/portal.html">Central de demandas</a>`)}<div class="product-grid">${panel('Dados do funcionário','Sua identidade e vínculo atual',`<form class="detail" id="profile-form"><div class="profile-grid"><div class="field"><label for="profile-name">Nome completo</label><input class="control" id="profile-name" name="fullName" maxlength="180" value="${esc(p.full_name)}" required></div><div class="field"><label for="profile-email">E-mail de trabalho</label><input class="control" id="profile-email" name="workEmail" type="email" maxlength="180" value="${esc(p.work_email)}"></div><div class="field"><label for="profile-title">Cargo ou função</label><input class="control" id="profile-title" name="jobTitle" maxlength="120" value="${esc(p.job_title)}"></div><div class="field"><label for="profile-number">Matrícula funcional</label><input class="control" id="profile-number" name="employeeNumber" maxlength="80" value="${esc(p.employee_number)}"></div><div class="field"><label for="profile-phone">Telefone profissional (opcional)</label><input class="control" id="profile-phone" name="workPhone" maxlength="60" value="${esc(p.work_phone)}"></div><div class="field"><label for="profile-hours">Horário de trabalho (opcional)</label><input class="control" id="profile-hours" name="workHours" maxlength="120" placeholder="Ex.: 8h às 14h" value="${esc(p.work_hours)}"></div><div class="field"><label>Secretaria</label><input class="control" value="${esc(p.department||'Sem vínculo cadastrado')}" disabled></div><div class="field"><label>Setor</label><input class="control" value="${esc(p.sector||'Sem setor cadastrado')}" disabled></div><div class="field"><label>Perfil de acesso</label><input class="control" value="${esc(p.role)}" disabled></div></div><p class="muted-note">O funcionário pode alterar seu nome e dados de contato; secretaria, setor e permissões são administrados separadamente.</p><button class="button button-primary" type="submit">Salvar perfil</button></form>`,'wide')}</div>`);}

function drawNotifications(){const list=S.notifications;const unread=list.filter(n=>!n.read_at).length;const prefs=S.notificationPrefs;shell(`${heading('Notificações',`${unread} não lida(s) · lembretes locais para tarefas e reuniões próximas.`,``)}<div class="product-grid">${panel('Avisos recentes','Marque cada aviso como lido',`<div class="notification-list">${list.length?list.map(n=>`<article class="notice-row ${n.read_at?'':'unread'}"><div><strong>${esc(n.message)}</strong><p class="row-meta">${fmtDate(n.due_at)} · ${esc(n.kind.replaceAll('_',' '))}</p></div>${n.read_at?'':`<button class="button" data-action="read-notification" data-id="${n.id}">Marcar lida</button>`}</article>`).join(''):empty('Você não tem notificações pendentes.')}</div>`,'wide')}${panel('Preferências','Ative ou desative cada tipo de aviso',`<form class="detail" id="notification-pref-form">${[['tarefa_atrasada','Tarefas atrasadas'],['tarefa_prazo','Prazos nas próximas 24 horas'],['tarefa_urgente','Tarefas urgentes em aberto'],['reuniao_proxima','Reuniões nas próximas 24 horas'],['documento_atencao','Documentos marcados para atenção']].map(([k,v])=>`<label class="toggle-row"><span>${v}</span><input type="checkbox" name="${k}" ${prefs[k]?'checked':''}></label>`).join('')}<button class="button button-primary" type="submit">Salvar preferências</button></form>`,'wide')}</div><p class="muted-note">Os avisos são exibidos dentro do SIGAM. Não há envio de e-mail, SMS ou push configurado.</p>`);}

function drawSearch(){const r=S.search||{tasks:[],events:[],documents:[],notes:[]};const groups=[['Tarefas',r.tasks,x=>`<strong>${esc(x.title)}</strong><p>${esc(labels[x.status])} · ${esc(priorityLabels[x.priority])} · ${fmtDate(x.due_at)}</p>`,`data-open-task`],['Reuniões e compromissos',r.events,x=>`<strong>${esc(x.title)}</strong><p>${esc(kindLabels[x.kind]||x.kind)} · ${fmtDate(x.starts_at)}${x.minutes?` · Ata: ${esc(x.minutes.slice(0,100))}`:''}</p>`,`data-open-event`],['Documentos',r.documents,x=>`<strong>${esc(x.title)}</strong><p>${esc(x.original_name)} · ${esc(categoryLabels[x.category]||x.category)}</p>`,null],['Notas de planejamento',r.notes,x=>`<strong>${fmtDate(x.plan_date,false)}</strong><p>${esc(x.priorities||x.daily_notes||x.weekly_goal)}</p>`,null]];shell(`${heading('Pesquisa global',S.q?`Resultados para “${S.q}”`:'Pesquise tarefas, reuniões, atas, documentos e notas.', '')}<form class="filters-row" id="global-search-form"><input class="control" id="global-search-page" name="q" type="search" value="${esc(S.q)}" placeholder="Digite pelo menos 2 caracteres…"><button class="button button-primary">Pesquisar</button></form><div class="search-results">${groups.map(([name,items,format,attr])=>panel(name,`${items.length} resultado(s)`,items.length?`<div class="product-list">${items.map(x=>`<article class="product-item" ${attr?`${attr}="${x.id}"`:''}><div class="product-item-main">${format(x)}</div>${attr?'':'<a class="button" href="/api/documents/'+x.id+'/download">Baixar</a>'}</article>`).join('')}</div>`:empty('Nenhum resultado nesta categoria.'),'')).join('')}</div>`);}

function showModal(title,content){document.getElementById('product-modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<div class="product-modal-backdrop" id="product-modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><section class="product-modal"><header class="product-modal-head"><h2>${esc(title)}</h2><button class="button" data-action="close-modal" aria-label="Fechar">Fechar</button></header><div class="product-modal-body">${content}</div></section></div>`);}
function closeModal(){document.getElementById('product-modal')?.remove();}
function openTaskForm(task=null,sourceEventId=null){const editing=!!task;showModal(editing?'Editar tarefa':'Nova tarefa',`<form id="task-form" data-id="${task?.id||''}"><div class="form-grid"><div class="field span-2"><label for="tf-title">Título</label><input class="control" id="tf-title" name="title" maxlength="180" required value="${esc(task?.title)}"></div><div class="field span-2"><label for="tf-description">Descrição</label><textarea class="control" id="tf-description" name="description" rows="3" maxlength="10000">${esc(task?.description)}</textarea></div><div class="field"><label for="tf-category">Categoria</label><input class="control" id="tf-category" name="category" maxlength="100" value="${esc(task?.category||'Geral')}"></div><div class="field"><label for="tf-priority">Prioridade</label><select class="control" id="tf-priority" name="priority">${Object.entries(priorityLabels).map(([k,v])=>`<option value="${k}" ${(task?.priority||'normal')===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="tf-status">Status</label><select class="control" id="tf-status" name="status">${Object.entries(labels).map(([k,v])=>`<option value="${k}" ${(task?.status||'aberta')===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="tf-start">Data de início (opcional)</label><input class="control" id="tf-start" name="startAt" type="datetime-local" value="${esc(localStamp(task?.start_at))}"></div><div class="field"><label for="tf-due">Prazo final (opcional)</label><input class="control" id="tf-due" name="dueAt" type="datetime-local" value="${esc(localStamp(task?.due_at))}"></div><div class="field span-2"><label for="tf-observations">Observações</label><textarea class="control" id="tf-observations" name="observations" rows="2" maxlength="5000">${esc(task?.observations)}</textarea></div></div>${sourceEventId?`<input type="hidden" name="sourceEventId" value="${sourceEventId}">`:task?.source_event_id?`<input type="hidden" name="sourceEventId" value="${task.source_event_id}">`:''}<p id="task-form-error" class="product-error" role="alert"></p><div class="product-form-actions"><button type="button" class="button" data-action="close-modal">Cancelar</button><button class="button button-primary" type="submit">${editing?'Salvar alterações':'Criar tarefa'}</button></div></form>`);}
async function openTaskDetail(id){try{const [t,history]=await Promise.all([api(`/tasks/${id}`),api(`/tasks/${id}/history`)]);showModal(t.title,`<div class="detail-facts"><div class="fact"><small>Status</small><span>${esc(labels[t.status])}</span></div><div class="fact"><small>Prioridade</small><span>${esc(priorityLabels[t.priority])}</span></div><div class="fact"><small>Prazo</small><span class="${dueLate(t)?'late':''}">${t.due_at?fmtDate(t.due_at):'Sem prazo'}</span></div><div class="fact"><small>Categoria</small><span>${esc(t.category)}</span></div></div><p>${esc(t.description||'Sem descrição.')}</p>${t.observations?`<p><strong>Observações:</strong> ${esc(t.observations)}</p>`:''}${t.completed_at?`<p class="muted-note">Concluída em ${fmtDate(t.completed_at)}</p>`:''}${t.source_event_id?`<p class="muted-note">Vinculada à reunião de origem.</p>`:''}${t.documents.length?`<h3>Documentos relacionados</h3>${t.documents.map(d=>`<p>${esc(d.title)} · ${esc(d.original_name)}</p>`).join('')}`:''}<div class="toolbar"><button class="button button-primary" data-action="edit-task" data-id="${id}">Editar</button><button class="button" data-action="history-task" data-id="${id}">Histórico (${history.length})</button><button class="button button-danger" data-action="archive-task" data-id="${id}">Arquivar</button></div><div id="task-history-detail"></div>`);}catch(e){toast(e.message);}}
async function showTaskHistory(id){const list=await api(`/tasks/${id}/history`);const node=document.getElementById('task-history-detail');if(node)node.innerHTML=`<div class="history"><h4>Histórico de alterações</h4>${list.map(x=>`<article class="event"><strong>${esc(x.action.replaceAll('_',' '))}</strong><p>${esc(x.details)}</p><time>${fmtDate(x.happened_at)}</time></article>`).join('')||empty('Sem histórico.')}</div>`;}
function openEventForm(event=null,kind='compromisso'){const editing=!!event;const selected=event?.kind||kind;showModal(editing?(selected==='reuniao'?'Editar reunião':'Editar compromisso'):(selected==='reuniao'?'Nova reunião':'Novo compromisso'),`<form id="event-form" data-id="${event?.id||''}"><div class="form-grid"><div class="field"><label for="ef-kind">Tipo</label><select class="control" name="kind" id="ef-kind">${Object.entries(kindLabels).map(([k,v])=>`<option value="${k}" ${selected===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="ef-status">Situação</label><select class="control" name="status" id="ef-status"><option value="agendada" ${(event?.status||'agendada')==='agendada'?'selected':''}>Agendada</option><option value="realizada" ${event?.status==='realizada'?'selected':''}>Realizada</option><option value="cancelada" ${event?.status==='cancelada'?'selected':''}>Cancelada</option></select></div><div class="field span-2"><label for="ef-title">Título</label><input class="control" id="ef-title" name="title" maxlength="180" required value="${esc(event?.title)}"></div><div class="field"><label for="ef-start">Data e horário inicial</label><input class="control" id="ef-start" name="startsAt" type="datetime-local" required value="${esc(localStamp(event?.starts_at))}"></div><div class="field"><label for="ef-end">Horário final (opcional)</label><input class="control" id="ef-end" name="endsAt" type="datetime-local" value="${esc(localStamp(event?.ends_at))}"></div><div class="field"><label for="ef-location">Local ou link</label><input class="control" id="ef-location" name="location" maxlength="240" value="${esc(event?.location)}"></div><div class="field"><label for="ef-participants">Participantes</label><input class="control" id="ef-participants" name="participants" maxlength="2000" value="${esc(event?.participants)}"></div><div class="field span-2"><label for="ef-description">Descrição</label><textarea class="control" id="ef-description" name="description" rows="2" maxlength="10000">${esc(event?.description)}</textarea></div><div class="field span-2"><label for="ef-agenda">Pauta</label><textarea class="control" id="ef-agenda" name="agenda" rows="2" maxlength="5000">${esc(event?.agenda)}</textarea></div><div class="field span-2"><label for="ef-objective">Objetivo</label><textarea class="control" id="ef-objective" name="objective" rows="2" maxlength="2000">${esc(event?.objective)}</textarea></div><div class="field span-2"><label for="ef-notes">Observações</label><textarea class="control" id="ef-notes" name="notes" rows="2" maxlength="5000">${esc(event?.notes)}</textarea></div>${selected==='reuniao'?`<div class="field span-2"><label for="ef-minutes">Ata resumida</label><textarea class="control" id="ef-minutes" name="minutes" rows="3" maxlength="10000">${esc(event?.minutes)}</textarea></div>`:''}</div><p id="event-form-error" class="product-error" role="alert"></p><div class="product-form-actions"><button type="button" class="button" data-action="close-modal">Cancelar</button><button class="button button-primary" type="submit">${editing?'Salvar alterações':'Salvar compromisso'}</button></div></form>`);}
async function openEventDetail(id){try{const [e,history]=await Promise.all([api(`/events/${id}`),api(`/events/${id}/history`)]);showModal(e.title,`<p><span class="badge">${esc(kindLabels[e.kind])}</span> <span class="badge">${esc(e.status)}</span></p><div class="detail-facts"><div class="fact"><small>Quando</small><span>${fmtDate(e.starts_at)}${e.ends_at?` – ${fmtDate(e.ends_at).split(' ').at(-1)}`:''}</span></div><div class="fact"><small>Local</small><span>${esc(e.location||'Não informado')}</span></div><div class="fact"><small>Participantes</small><span>${esc(e.participants||'Não informados')}</span></div></div>${e.description?`<p>${esc(e.description)}</p>`:''}${e.agenda?`<h3>Pauta</h3><p>${esc(e.agenda)}</p>`:''}${e.objective?`<h3>Objetivo</h3><p>${esc(e.objective)}</p>`:''}${e.conflicts.length?`<div class="conflict-notice">Conflito: ${e.conflicts.map(x=>esc(x.title)).join(', ')}</div>`:''}${e.kind==='reuniao'?`<form id="minutes-form" data-id="${id}"><div class="field"><label for="meeting-minutes">Ata resumida</label><textarea class="control" id="meeting-minutes" name="minutes" rows="5" maxlength="10000">${esc(e.minutes)}</textarea></div><button class="button button-primary" type="submit">Salvar ata</button></form><hr><form id="meeting-task-form" data-id="${id}"><h3>Criar tarefa de encaminhamento</h3><div class="field"><label for="mt-title">Título da tarefa</label><input class="control" id="mt-title" name="title" maxlength="180" required></div><div class="field"><label for="mt-due">Prazo (opcional)</label><input class="control" id="mt-due" name="dueAt" type="datetime-local"></div><div class="field"><label for="mt-priority">Prioridade</label><select class="control" id="mt-priority" name="priority"><option value="normal">Normal</option><option value="alta">Alta</option><option value="urgente">Urgente</option><option value="baixa">Baixa</option></select></div><button class="button" type="submit">Criar tarefa vinculada</button></form>`:''}<div class="toolbar"><button class="button button-primary" data-action="edit-event" data-id="${id}">Editar</button>${e.kind==='reuniao'?`<button class="button" data-action="new-task-from-event" data-id="${id}">Nova tarefa vinculada</button>`:''}<button class="button button-danger" data-action="delete-event" data-id="${id}">Excluir</button><button class="button" data-action="event-history" data-id="${id}">Histórico (${history.length})</button></div><div id="event-history-detail"></div>`);}catch(e){toast(e.message);}}
function openDocumentForm(document=null){const editing=!!document;const taskOptions=S.tasks.map(t=>`<option value="${t.id}" ${document?.linked_task_id===t.id?'selected':''}>${esc(t.title)}</option>`).join('');const eventOptions=S.events.map(e=>`<option value="${e.id}" ${document?.linked_event_id===e.id?'selected':''}>${esc(e.title)}</option>`).join('');showModal(editing?'Editar documento':'Adicionar documento',`<form id="document-form" data-id="${document?.id||''}"><div class="field"><label for="df-title">Título</label><input class="control" id="df-title" name="title" maxlength="180" required value="${esc(document?.title)}"></div>${editing?'':`<div class="field"><label for="df-file">Arquivo (até 8 MB)</label><input class="control" id="df-file" name="file" type="file" accept=".pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.txt,.csv,.png,.jpg,.jpeg" required></div>`}<div class="field"><label for="df-category">Categoria</label><select class="control" id="df-category" name="category">${Object.entries(categoryLabels).map(([k,v])=>`<option value="${k}" ${(document?.category||'outros')===k?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label for="df-description">Descrição</label><textarea class="control" id="df-description" name="description" rows="3" maxlength="5000">${esc(document?.description)}</textarea></div><div class="field"><label for="df-tag">Etiqueta</label><input class="control" id="df-tag" name="tag" maxlength="120" value="${esc(document?.tag)}"></div><label class="toggle-row"><span>Precisa de atenção</span><input type="checkbox" name="needsAttention" ${document?.attention?'checked':''}></label><div class="field"><label for="df-task">Associar à tarefa (opcional)</label><select class="control" id="df-task" name="linkedTaskId"><option value="">Nenhuma</option>${taskOptions}</select></div><div class="field"><label for="df-event">Associar à reunião/compromisso (opcional)</label><select class="control" id="df-event" name="linkedEventId"><option value="">Nenhum</option>${eventOptions}</select></div><p id="document-form-error" class="product-error" role="alert"></p><div class="product-form-actions"><button type="button" class="button" data-action="close-modal">Cancelar</button><button class="button button-primary" type="submit">${editing?'Salvar':'Enviar arquivo'}</button></div></form>`);}
async function showEventHistory(id){const list=await api(`/events/${id}/history`);const node=document.getElementById('event-history-detail');if(node)node.innerHTML=`<div class="history"><h4>Histórico</h4>${list.map(x=>`<article class="event"><strong>${esc(x.action)}</strong><p>${esc(x.details)}</p><time>${fmtDate(x.happened_at)}</time></article>`).join('')}</div>`;}

app.addEventListener('click',async event=>{const page=event.target.closest('[data-page]');if(page){await loadPage(page.dataset.page);return;}const task=event.target.closest('[data-open-task]');if(task){await openTaskDetail(Number(task.dataset.openTask));return;}const meeting=event.target.closest('[data-open-event]');if(meeting){await openEventDetail(Number(meeting.dataset.openEvent));return;}const button=event.target.closest('[data-action]');if(!button)return;const id=Number(button.dataset.id);
 try{switch(button.dataset.action){case'menu':document.getElementById('product-nav')?.classList.toggle('open');break;case'close-modal':closeModal();break;case'logout':await api('/logout',{method:'POST',body:{}});S.user=null;renderSignedOut();break;case'reload':loadPage();break;case'new-task':openTaskForm();break;case'new-event':openEventForm();break;case'new-meeting':openEventForm(null,'reuniao');break;case'new-document':S.tasks=await api('/tasks');S.events=await api('/events');openDocumentForm();break;case'task-view':S.taskView=button.dataset.view;drawTasks();break;case'edit-task':{const task=await api(`/tasks/${id}`);closeModal();openTaskForm(task);break;}case'archive-task':if(confirm('Arquivar esta tarefa? Ela sairá da lista, e o histórico será mantido.')){await api(`/tasks/${id}`,{method:'DELETE'});closeModal();toast('Tarefa arquivada.');await loadPage('tarefas');}break;case'history-task':await showTaskHistory(id);break;case'calendar-view':S.calendarView=button.dataset.view;await loadPage('agenda');break;case'calendar-prev':moveCalendar(-1);break;case'calendar-next':moveCalendar(1);break;case'calendar-today':S.day=today();await loadPage('agenda');break;case'edit-event':{const e=await api(`/events/${id}`);closeModal();openEventForm(e);break;}case'delete-event':if(confirm('Excluir este compromisso? Tarefas e documentos vinculados perderão apenas o vínculo.')){await api(`/events/${id}`,{method:'DELETE'});closeModal();toast('Compromisso excluído.');await loadPage(S.page);}break;case'event-history':await showEventHistory(id);break;case'new-task-from-event':{const e=await api(`/events/${id}`);closeModal();openTaskForm(null,e.id);break;}case'edit-document':{S.tasks=await api('/tasks');S.events=await api('/events');const d=await api(`/documents/${id}`);openDocumentForm(d);break;}case'archive-document':if(confirm('Arquivar este documento? Ele deixará de aparecer e de ser baixável.')){await api(`/documents/${id}`,{method:'DELETE'});toast('Documento arquivado.');await loadPage('documentos');}break;case'read-notification':await api(`/notifications/${id}/read`,{method:'POST',body:{}});await loadPage('notificacoes');break;default:break;}}catch(e){toast(e.message);}});

function moveCalendar(direction){const d=new Date(`${S.day}T12:00:00`);const step=S.calendarView==='mes'?'month':S.calendarView==='semana'?'week':'day';if(step==='month')d.setMonth(d.getMonth()+direction);else d.setDate(d.getDate()+direction*(step==='week'?7:1));S.day=toDateKey(d);loadPage('agenda');}
app.addEventListener('change',async event=>{const t=event.target;if(['task-status','task-priority','task-sort','task-from','task-to'].includes(t.id)){S.taskStatus=document.getElementById('task-status').value;S.taskPriority=document.getElementById('task-priority').value;S.taskSort=document.getElementById('task-sort').value;S.taskQuery=document.getElementById('task-search').value;S.taskFrom=document.getElementById('task-from').value;S.taskTo=document.getElementById('task-to').value;await loadPage('tarefas');}else if(t.matches('[data-task-status]')){const id=Number(t.dataset.taskStatus);try{await api(`/tasks/${id}`,{method:'PUT',body:{status:t.value}});toast('Status da tarefa atualizado.');await loadPage('tarefas');}catch(e){toast(e.message);}}else if(t.id==='document-category'){S.docCategory=t.value;await loadDocuments();}else if(['document-from','document-to'].includes(t.id)){S.docFrom=document.getElementById('document-from').value;S.docTo=document.getElementById('document-to').value;await loadDocuments();}else if(t.id==='meeting-from'||t.id==='meeting-to'){S.meetingFrom=document.getElementById('meeting-from').value;S.meetingTo=document.getElementById('meeting-to').value;await loadPage('reunioes');}});
app.addEventListener('input',event=>{if(event.target.id==='meeting-search'){S.meetingQuery=event.target.value;const cursor=event.target.selectionStart;drawMeetings();const input=document.getElementById('meeting-search');input?.focus();input?.setSelectionRange(cursor,cursor);}if(event.target.id==='document-search'){S.docQuery=event.target.value;clearTimeout(window.__docSearchTimer);window.__docSearchTimer=setTimeout(loadDocuments,300);}if(event.target.id==='task-search'){S.taskQuery=event.target.value;clearTimeout(window.__taskSearchTimer);window.__taskSearchTimer=setTimeout(async()=>{await loadPage('tarefas');const input=document.getElementById('task-search');input?.focus();input?.setSelectionRange(S.taskQuery.length,S.taskQuery.length);},350);}});
async function loadDocuments(){try{const q=encodeURIComponent(S.docQuery||'');const category=encodeURIComponent(S.docCategory||'');const from=encodeURIComponent(S.docFrom||'');const to=encodeURIComponent(S.docTo||'');S.docs=await api(`/documents?q=${q}&category=${category}&from=${from}&to=${to}`);drawDocuments();const qEl=document.getElementById('document-search');if(qEl){qEl.value=S.docQuery;document.getElementById('document-category').value=S.docCategory;document.getElementById('document-from').value=S.docFrom;document.getElementById('document-to').value=S.docTo;qEl.focus();qEl.setSelectionRange(S.docQuery.length,S.docQuery.length);}}catch(e){toast(e.message);}}
app.addEventListener('submit',async event=>{event.preventDefault();const form=event.target;try{
 if(form.id==='top-search-form'||form.id==='global-search-form'){S.q=new FormData(form).get('q')||'';S.search=await searchData(S.q);await loadPage('pesquisa');return;}
 if(form.id==='task-form'){const data=Object.fromEntries(new FormData(form));const id=form.dataset.id;for(const k of ['startAt','dueAt'])if(!data[k])data[k]=null;if(data.sourceEventId)data.sourceEventId=Number(data.sourceEventId);const saved=await api(id?`/tasks/${id}`:'/tasks',{method:id?'PUT':'POST',body:data});closeModal();toast(id?'Tarefa atualizada.':'Tarefa criada.');if(S.page==='inicio')await loadPage('inicio');else await loadPage('tarefas');return;}
 if(form.id==='event-form'){const data=Object.fromEntries(new FormData(form));const id=form.dataset.id;for(const k of ['endsAt'])if(!data[k])data[k]=null;const saved=await api(id?`/events/${id}`:'/events',{method:id?'PUT':'POST',body:data});closeModal();toast(id?'Compromisso atualizado.':'Compromisso salvo.');if(saved.conflicts?.length)toast(`Atenção: há ${saved.conflicts.length} conflito(s) de horário.`);await loadPage(S.page);return;}
 if(form.id==='minutes-form'){const id=form.dataset.id;const result=await api(`/events/${id}`,{method:'PUT',body:{minutes:new FormData(form).get('minutes')}});toast('Ata salva.');await openEventDetail(Number(id));return;}
 if(form.id==='meeting-task-form'){const id=form.dataset.id;const data=Object.fromEntries(new FormData(form));if(!data.dueAt)data.dueAt=null;await api(`/events/${id}/tasks`,{method:'POST',body:data});toast('Tarefa vinculada à reunião criada.');closeModal();await loadPage('tarefas');return;}
 if(form.id==='document-form'){const id=form.dataset.id;const data=Object.fromEntries(new FormData(form));data.needsAttention=form.elements.needsAttention.checked;data.linkedTaskId=data.linkedTaskId?Number(data.linkedTaskId):null;data.linkedEventId=data.linkedEventId?Number(data.linkedEventId):null;if(id){await api(`/documents/${id}`,{method:'PUT',body:data});}else{const file=document.getElementById('df-file').files[0];if(!file)throw new Error('Selecione um arquivo.');const b64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=()=>reject(new Error('Não foi possível ler o arquivo.'));reader.readAsDataURL(file);});data.fileName=file.name;data.fileBase64=b64;await api('/documents',{method:'POST',body:data});}closeModal();toast(id?'Documento atualizado.':'Documento enviado em área privada.');await loadPage('documentos');return;}
 if(form.id==='profile-form'){S.profile=await api('/profile',{method:'PUT',body:Object.fromEntries(new FormData(form))});S.user.name=S.profile.full_name;toast('Perfil salvo.');await loadPage('perfil');return;}
 if(form.id==='plan-form'){S.plan=await api('/plan',{method:'PUT',body:{date:today(),...Object.fromEntries(new FormData(form))}});toast('Planejamento salvo.');await loadPage('planejamento');return;}
 if(form.id==='notification-pref-form'){const preferences={};new FormData(form).forEach((_,key)=>preferences[key]=true);for(const key of ['tarefa_atrasada','tarefa_prazo','tarefa_urgente','reuniao_proxima','documento_atencao'])preferences[key]=form.elements[key].checked;S.notificationPrefs=await api('/notifications/preferences',{method:'PUT',body:{preferences}});toast('Preferências de aviso atualizadas.');await loadPage('notificacoes');return;}
 }catch(error){const node=form.querySelector('.product-error');if(node)node.textContent=error.message;else toast(error.message);}});

function renderSignedOut(){app.innerHTML=`<div class="login-wrap"><section class="login-card"><div class="brand"><div class="brand-mark">S</div><div><h1>SIGAM</h1><p>Organização pessoal de trabalho</p></div></div><h2>Entre para acessar sua rotina</h2><p>Entre na área interna para usar tarefas, agenda, documentos e planejamento pessoal.</p><a class="button button-primary" href="/portal.html">Abrir login do funcionário</a></section></div>`;}
async function init(){try{S.user=await api('/me');S.csrf=S.user.csrfToken;await loadPage('inicio');}catch{renderSignedOut();}}
init();

